50	     9	/**
51	    10	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
52	    11	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
53	    12	 * (half-even) at every step.
54	    13	 */
55	    14	public final class PriceCalculator {
56	    15	
57	    16	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
58	    17	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
59	    18	
60	    19	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
61	    20	        int nights = 0;
62	    21	        BigDecimal subtotal = cents(BigDecimal.ZERO);
63	    22	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
64	    23	            subtotal = subtotal.add(nightPrice(room, night));
65	    24	            nights++;
66	    25	        }
67	    26	        BigDecimal discount = switch (ratePlan) {
68	    27	            case STANDARD -> cents(BigDecimal.ZERO);
69	    28	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
70	    29	        };
71	    30	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
72	    31	    }
73	    32	
74	    33	    BigDecimal nightPrice(Room room, LocalDate night) {
75	    34	        BigDecimal nightlyRate = room.nightlyRate();
76	    35	        if (isHighSeason(night)) {
77	    36	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
78	    37	        }
79	    38	        return cents(nightlyRate);
80	    39	    }
81	    40	
82	    41	    /** High season: from December 15 to the end of February, and the whole of July. */
83	    42	    static boolean isHighSeason(LocalDate date) {
84	    43	        Month month = date.getMonth();
85	    44	        return month == Month.JANUARY
86	    45	                || month == Month.FEBRUARY
87	    46	                || month == Month.JULY
88	    47	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
89	    48	    }
90	    49	
91	    50	    static BigDecimal cents(BigDecimal value) {
92	    51	        return value.setScale(2, RoundingMode.HALF_EVEN);
93	    52	    }
94	    53	}
